-- Taxonomy overhaul: persist canonical goal-category routes for substances the
-- importer left unrouted, and fill risk_level via rule-based inference. Computed
-- offline from a full catalog dump using the app's own read-time inference rules;
-- reviewed in taxonomy-review.csv (see PR). Idempotent throughout. The 3
-- classification-change candidates were review-rejected false positives — no
-- classification is touched.

-- 1. Canonical goal categories under their correct domains (the read-time
--    fallback mislabeled every inferred category as domain 'Body').
insert into category_routes (domain, category)
select domain, category from (values
    ('CG','Mind','Cognition'),
    ('RC','Mind','Recovery'),
    ('PF','Body','Performance'),
    ('LG','Vitality','Longevity'),
    ('MS','Mind','Mood & Stress'),
    ('MH','Vitality','Metabolic Health'),
    ('HH','Vitality','Hormonal Health'),
    ('DH','Vitality','Digestive Health'),
    ('HT','Vitality','Heart Health'),
    ('PI','Body','Pain & Injury'),
    ('JM','Body','Joint & Mobility'),
    ('BS','Body','Beauty & Skin')
) as codes(code, domain, category)
on conflict (domain, category) do nothing;

-- 2. Route links for currently-unrouted substances, encoded compactly as
--    slug -> comma-joined category codes.
with codes(code, domain, category) as (values
    ('CG','Mind','Cognition'),
    ('RC','Mind','Recovery'),
